/// <summary>
/// ApplicationsInsights class to log events
/// </summary>
public class OMGApplicationInsights implements System.IDisposable
{
    protected SysApplicationInsightsEventTelemetry eventTelemetry;
    protected System.Diagnostics.Stopwatch stopwatch;

}

Method.Source:
/// <summary>
/// Called when the object is instantiated
/// </summary>
/// <param name = "_applicationInsightsLogObject">OMGApplicationInsights</param>
delegate void OnInstantiated(OMGApplicationInsights _applicationInsightsLogObject) {}

/// <summary>
/// Called when the object is disposed
/// </summary>
/// <param name = "_applicationInsightsLogObject">OMGApplicationInsights</param>
delegate void OnDisposing(OMGApplicationInsights _applicationInsightsLogObject) {}

protected void new(str _eventName)
{
    this.eventTelemetry = SysApplicationInsightsEventTelemetry::newFromEventIdName('OMG', _eventName);

    stopwatch = System.Diagnostics.Stopwatch::StartNew();

    this.OnInstantiated(this);
}

/// <summary>
/// Add TypeId property to the event
/// </summary>
/// <param name = "_messageTypeId">MessageTypeId</param>
public void addMessageTypeIdProperty(OMGMessageTypeId _messageTypeId)
{
    SysApplicationInsightsProperty property = OMGApplicationInsightsMessageTypeIdProperty::newFromValue(_messageTypeId);
    eventTelemetry.addProperty(property);
}

/// <summary>
/// Add Duration property to the event
/// </summary>
/// <param name = "_duration">Duration</param>
public void addDurationProperty(int64 _duration)
{
    SysApplicationInsightsProperty property = OMGApplicationInsightsDurationProperty::newFromDuration(_duration);
    eventTelemetry.addProperty(property);
}

/// <summary>
/// Add RecordCount property to the event
/// </summary>
/// <param name = "_recordCount">RecordCount</param>
public void addMessageCountProperty(int64 _recordCount)
{
    SysApplicationInsightsProperty property = OMGApplicationInsightsMessageCountProperty::newFromRecordCount(_recordCount);
    eventTelemetry.addProperty(property);
}

/// <summary>
/// Add MessageSize property to the event
/// </summary>
/// <param name = "_messageSize">MessageSize</param>
public void addMessageSizeProperty(int64 _messageSize)
{
    SysApplicationInsightsProperty property = OMGApplicationInsightsMessageSizeProperty::newFromMessageSize(_messageSize);
    eventTelemetry.addProperty(property);
}

/// <summary>
/// Stop the timer
/// </summary>
public void stopTimer()
{
    stopwatch.Stop();
}

/// <summary>
/// Add the telemetry to ApplicationInsights and dispose the object
/// </summary>
public void dispose()
{
    this.OnDisposing(this);

    if (stopwatch.IsRunning)
    {
        stopwatch.Stop();
    }

    this.addDurationProperty(stopwatch.ElapsedMilliseconds);
    SysApplicationInsightsTelemetryLogger::instance().trackEvent(eventTelemetry);
}
